<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref, watch } from 'vue'
import type { BusinessRecord, Column, CommandForm, DataSeries, Observation, SessionUser } from './types'
import { date, fmt, label, tone } from './labels'
import { downloadCsv, request } from './api'
import Icon from './Icon.vue'
import RecordTable from './RecordTable.vue'
import SeriesChart from './SeriesChart.vue'
import CommandDialog from './CommandDialog.vue'
import DataImport from './DataImport.vue'
const props=defineProps<{page:string;user:SessionUser;projectId:string}>()
const emit=defineEmits<{reference:[reportId:string]}>()
type Catalog={sources:Record<string,unknown>[];series:DataSeries[];models:{id:string;name:string}[];operators:{id:string;name:string}[]}
const catalog=ref<Catalog|null>(null), selectedSeries=ref(''), observations=ref<Observation[]>([]), queryWarnings=ref<string[]>([])
const loading=ref(false),loadError=ref(''),researchError=ref(''),notice=ref('')
const datasets=ref<BusinessRecord[]>([]),factors=ref<BusinessRecord[]>([]),runs=ref<BusinessRecord[]>([]),reports=ref<BusinessRecord[]>([])
const form=ref<CommandForm|null>(null),modalBusy=ref(false),modalError=ref(''),modalPath=ref('')
const selectedRun=ref<BusinessRecord|null>(null),selectedReport=ref<BusinessRecord|null>(null)
const importOpen=ref(false)
let querySequence=0,alive=true
watch(selectedSeries,()=>{querySequence++;observations.value=[];queryWarnings.value=[];loadError.value='';loading.value=false},{flush:'sync'})
onBeforeUnmount(()=>{alive=false;querySequence++})
const startDate=ref(''),endDate=ref(''),asOf=ref(new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'})),availability=ref('source_published')
const series=computed(()=>catalog.value?.series.find(s=>s.id===selectedSeries.value))
const source=computed(()=>catalog.value?.sources.find(s=>s.id===series.value?.source_id))
const available=computed(()=>catalog.value?.series.filter(s=>['available','fixture','manual_unverified'].includes(s.status||''))||[])
const lastValue=computed(()=>observations.value.filter(o=>o.value!=null).at(-1))
const ratioSeries=computed(()=>['比例','ratio','fraction'].includes(series.value?.unit||''))
const latestDisplay=computed(()=>lastValue.value?.value==null?'—':fmt(lastValue.value.value*(ratioSeries.value?100:1),ratioSeries.value?4:2))
const canResearch=computed(()=>props.user.role==='operator')
const runCols:Column[]=[{key:'name',label:'实验名称',secondary:'id',width:'200px'},{key:'model_id',label:'注册模型'},{key:'target',label:'研究目标'},{key:'status',label:'任务状态',format:'status'},{key:'created_at',label:'运行时间',format:'date'}]
const reportCols:Column[]=[{key:'name',label:'研究报告',secondary:'id',width:'220px'},{key:'run_id',label:'来源实验'},{key:'share_scope',label:'共享范围',format:'status'},{key:'version',label:'版本'},{key:'created_at',label:'生成时间',format:'date'}]
const dataCols=computed<Column[]>(()=>[{key:'date',label:'统计期间 / 交易日'},{key:'value',label:ratioSeries.value?'观测值（%）':'观测值',format:ratioSeries.value?'percent':'number'},{key:'source_published_at',label:'来源发布时间',format:'date'},{key:'source_revision',label:'来源修订'},{key:'statistic_status',label:'统计属性'},{key:'release_id',label:'发布版本'},{key:'quality_flag',label:'质量标识'}])
function exportObservations(records:BusinessRecord[]){if(!ratioSeries.value){downloadCsv('玉米数据观测',dataCols.value,records);return}downloadCsv('玉米数据观测', [...dataCols.value,{key:'raw_ratio',label:'比例原值'}],records.map(r=>({...r,raw_ratio:r.value,value:r.value==null?'':(Number(r.value)*100).toFixed(4)})))}
async function query(){const seq=++querySequence;const seriesId=selectedSeries.value;loading.value=true;loadError.value="";observations.value=[];queryWarnings.value=[];try{const r=await request<{series:DataSeries;observations:Observation[];warnings:string[]}> ("/data/query",{series_id:seriesId,...(startDate.value?{start_date:startDate.value}:{}),...(endDate.value?{end_date:endDate.value}:{}),as_of:`${asOf.value}T23:59:59+08:00`,availability_mode:availability.value});if(!alive||seq!==querySequence||seriesId!==selectedSeries.value)return;observations.value=r.observations;queryWarnings.value=r.warnings||[]}catch(e){if(alive&&seq===querySequence){observations.value=[];loadError.value=(e as Error).message}}finally{if(alive&&seq===querySequence)loading.value=false}}
async function loadResearch(){researchError.value='';const results=await Promise.allSettled(['datasets','factors','runs','reports'].map(path=>request<{items:BusinessRecord[]}>(`/research/${path}?project_id=${encodeURIComponent(props.projectId)}`)));const targets=[datasets,factors,runs,reports];results.forEach((r,i)=>{if(r.status==='fulfilled')targets[i]!.value=r.value.items;else researchError.value=(r.reason as Error).message})}
async function imported(){catalog.value=await request<Catalog>('/data/catalog');notice.value='标准文件已导入服务端，新序列保留人工导入及核验状态。'}
async function init(){loading.value=true;loadError.value='';try{catalog.value=await request<Catalog>('/data/catalog');selectedSeries.value=available.value[0]?.id||catalog.value.series[0]?.id||'';if(selectedSeries.value)await query();await loadResearch()}catch(e){loadError.value=(e as Error).message}finally{loading.value=false}}
function open(path:string,definition:CommandForm){modalPath.value=path;form.value=definition;modalError.value=''}
function createDataset(){open('/research/datasets',{title:'冻结研究数据快照',description:'以当前数据查询和可得时点冻结快照，后续修订不覆盖已保存研究。',command:'dataset',fields:[{key:'name',label:'数据集名称',required:true,value:`${series.value?.name||'玉米数据'}研究快照`},{key:'series_id',label:'指标序列',type:'select',required:true,value:selectedSeries.value,options:available.value.map(s=>({value:s.id,label:s.name}))},{key:'start_date',label:'样本起日',type:'date',required:true,value:startDate.value||observations.value[0]?.date||'2020-01-01'},{key:'end_date',label:'样本止日',type:'date',required:true,value:endDate.value||observations.value.at(-1)?.date||asOf.value},{key:'as_of',label:'信息截止日',type:'date',required:true,value:asOf.value},{key:'availability_mode',label:'历史可用时点',type:'select',value:availability.value,required:true,options:[{value:'source_published',label:'依据来源发布时间'},{value:'platform_available',label:'依据平台首次可用时间'}]}],map:v=>({...v,as_of:`${v.as_of}T23:59:59+08:00`,project_id:props.projectId}),submitLabel:'保存只读快照'})}
function createFactor(){open('/research/factors',{title:'配置研究因子',description:'使用受控算子构建因子，无需编写代码。公式错误、零分母或缺值会返回原因。',command:'factor',fields:[{key:'name',label:'因子名称',required:true,value:'玉米价格滚动波动'},{key:'operator',label:'因子算子',type:'select',value:catalog.value?.operators.find(x=>x.id==='volatility')?.id||catalog.value?.operators[0]?.id,required:true,options:catalog.value?.operators.map(o=>({value:o.id,label:o.name}))},{key:'input_field',label:'输入字段',value:'value',readonly:true},{key:'window',label:'观察窗口（期）',type:'number',required:true,min:2,max:120,value:20},{key:'lag',label:'滞后期数',type:'number',required:true,min:1,max:120,value:1}],map:v=>({...v,project_id:props.projectId}),note:'新建因子生成独立版本；当前因子属于研究假设，不会写回保单。',submitLabel:'保存因子版本'})}
function datesForRun(){const ds=datasets.value[0];const obs=(ds?.observations as Observation[]|undefined)||observations.value;const dates=obs.filter(x=>x.value!=null).map(x=>x.date);return {train:dates[Math.floor(dates.length*.6)]||'2024-01-01',validation:dates[Math.floor(dates.length*.8)]||'2025-01-01',test:dates.at(-1)||asOf.value}}
function createRun(){const d=datesForRun();open('/research/runs',{title:'运行保险业务研究实验',description:'选择冻结样本、已注册模型及因子。价格预测与赔付风险分别验证，实验不会自动触发承保或交易。',command:'run',fields:[{key:'name',label:'实验名称',required:true,value:'玉米价格参考与历史验证'},{key:'dataset_id',label:'冻结数据集',type:'select',required:true,value:datasets.value[0]?.id||'',options:datasets.value.map(x=>({value:x.id,label:String(x.name||x.id)}))},{key:'target',label:'研究任务',type:'select',required:true,value:'price',options:[{value:'price',label:'价格参考（元/吨）'},{value:'payout',label:'保险赔付风险（元）'}]},{key:'model_id',label:'已注册模型',type:'select',required:true,value:catalog.value?.models[0]?.id||'naive_last',options:catalog.value?.models.map(x=>({value:x.id,label:x.name}))},{key:'factor_id',label:'研究因子（可选）',type:'select',value:factors.value[0]?.id||'',options:[{value:'',label:'不添加因子'},...factors.value.map(x=>({value:x.id,label:String(x.name||x.id)}))]},{key:'window',label:'模型窗口（期）',type:'number',required:true,min:2,max:60,value:5},{key:'train_end',label:'训练集截止日',type:'date',required:true,value:d.train},{key:'validation_end',label:'验证集截止日',type:'date',required:true,value:d.validation},{key:'test_end',label:'测试集截止日',type:'date',required:true,value:d.test},{key:'strike',label:'研究假设保障价格（元/吨）',type:'number',value:2400,required:true},{key:'quantity',label:'研究假设数量（吨）',type:'number',value:100,required:true}],map:v=>{const{factor_id,window,strike,quantity,...rest}=v;return{...rest,factor_ids:factor_id?[factor_id]:[],parameters:v.model_id==='moving_average'?{window}:v.model_id==='factor_ridge'?{alpha:1}:{},policy_terms:{strike,quantity},project_id:props.projectId}},note:'截止时点、时间切分、因子和模型随实验保存。样本不足或验证失败会如实显示。',submitLabel:'运行并历史验证'})}
function createReport(run:BusinessRecord){open('/research/reports',{title:'生成研究报告',description:'保存本次输入、模型、验证及结论为只读版本，可共享并引用至风险方案。',command:'report',fields:[{key:'name',label:'报告名称',value:`${run.name||'玉米研究'} · 业务意见`,required:true},{key:'conclusion',label:'业务结论与使用限制',type:'textarea',required:true,value:'请结合样本覆盖、历史误差及当前业务责任复核，研究结果仅作业务判断参考。'},{key:'share_scope',label:'共享范围',type:'select',value:'team',required:true,options:[{value:'private',label:'仅本人可见'},{value:'team',label:'本项目团队可见'}]}],map:v=>({...v,run_id:run.id,project_id:props.projectId}),submitLabel:'保存报告版本'})}
async function submit(values:Record<string,unknown>){modalBusy.value=true;modalError.value='';try{const result=await request<BusinessRecord>(modalPath.value,values);form.value=null;notice.value='已保存至服务端；研究版本与业务记录分别管理。';await loadResearch();if(modalPath.value==='/research/runs')selectedRun.value=result;if(modalPath.value==='/research/reports')selectedReport.value=result}catch(e){modalError.value=(e as Error).message}finally{modalBusy.value=false}}
const metrics=computed(()=>selectedRun.value?.metrics as {model?:Record<string,number>;baseline?:Record<string,number>}|undefined)
const predictions=computed(()=>((selectedRun.value?.predictions||[]) as Record<string,unknown>[]))
const validation=computed(()=>selectedRun.value?.validation as Record<string,unknown>|undefined)
const reportSections=computed(()=>selectedReport.value?Object.entries(selectedReport.value).filter(([k])=>!['id','name','created_at','owner_id','version'].includes(k)):[])
function display(v:unknown){return typeof v==='object'?JSON.stringify(v,null,2):String(v??'—')}
function downloadReport(r:BusinessRecord){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(r,null,2)],{type:'application/json'}));a.download=`${r.name||r.id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
onMounted(init)
</script>
<template>
<div v-if="loadError || researchError" class="gg-error" role="alert"><Icon name="warning" :size="18"/><span>{{ loadError || researchError }}</span><button class="gg-text-btn" @click="init">重新加载</button></div>
<div v-if="notice" class="gg-success-note" role="status"><Icon name="check" :size="17"/>{{ notice }}<button class="gg-icon-btn" aria-label="关闭提示" @click="notice=''"><Icon name="close" :size="16"/></button></div>
<template v-if="page==='data'">
 <div class="gg-context-strip"><span><Icon name="research" :size="17"/>来源、发布时间与版本可追溯</span><p>行情作合同采价或研究使用，贸易与供需按来源口径浏览</p><button v-if="canResearch" class="gg-btn" @click="importOpen=true"><Icon name="upload" :size="16"/>标准文件导入</button></div>
 <section class="gg-card gg-data-query"><div class="gg-card-heading"><div><h2>玉米主题数据浏览</h2><p>具体合约、贸易与供需在同一指标契约下查询</p></div><span class="gg-chip">{{ available.length }} 条已接入序列</span></div><div class="gg-query-grid"><label class="gg-field gg-query-series"><span>指标 / 合约 / 国家</span><select v-model="selectedSeries" aria-label="选择数据指标"><option v-for="s in catalog?.series" :key="s.id" :value="s.id">{{ s.name }}{{ s.status!=='available' ? ` · ${label(s.status)}` : '' }}</option></select></label><label class="gg-field"><span>样本起日</span><input v-model="startDate" aria-label="样本起日" type="date"/></label><label class="gg-field"><span>样本止日</span><input v-model="endDate" aria-label="样本止日" type="date"/></label><button class="gg-btn gg-btn-primary" :disabled="loading || !selectedSeries" @click="query"><span v-if="loading" class="gg-spinner"/><Icon v-else name="search" :size="16"/>查询</button></div><details class="gg-query-advanced"><summary>历史可用时点与版本</summary><div class="gg-form-grid"><label class="gg-field"><span>信息截止日</span><input v-model="asOf" type="date"/></label><label class="gg-field"><span>历史可用时点</span><select v-model="availability"><option value="source_published">来源发布时间</option><option value="platform_available">平台首次可用时间</option></select></label></div></details></section>
 <section class="gg-card gg-series-panel"><div class="gg-card-heading"><div><span class="gg-overline">{{ source?.name || series?.source || '来源待确认' }}</span><h2>{{ series?.name || '选择指标查看数据' }}</h2><p>{{ series?.definition || series?.description || '指标定义及使用口径随查询结果显示' }}</p></div><div class="gg-series-value"><strong>{{ latestDisplay }}<small>{{ ratioSeries?"%":series?.unit }}</small></strong><span>{{ lastValue?.date || '暂无观测' }}</span></div></div><div v-if="loading" class="gg-loading"><span class="gg-spinner"/>正在读取来源数据…</div><SeriesChart v-else :points="observations" :unit="series?.unit"/><div class="gg-series-foot"><span><i class="gg-dot gg-dot-indigo"/>{{ observations.length }} 个观测 · 缺失不补零</span><button v-if="canResearch" class="gg-text-btn" :disabled="!observations.length" @click="createDataset">带入研究并冻结快照<Icon name="arrow" :size="15"/></button></div></section>
 <div v-for="w in queryWarnings" :key="w" class="gg-notice"><Icon name="info" :size="16"/><span>{{ w }}</span></div>
 <RecordTable title="观测与发布版本" :records="observations.map((o,i)=>({...o,id:String(i),version:1,status:o.quality_flag||''}))" :columns="dataCols" :selectable="false" @export="exportObservations"/>
 <section class="gg-card"><div class="gg-card-heading"><div><h2>数据来源与统计口径</h2><p>按业务主题、来源和发布版本浏览，保留完整统计口径</p></div><Icon name="building" :size="20"/></div><div class="gg-source-grid"><article v-for="s in catalog?.sources" :key="String(s.id)"><div><strong>{{ s.name }}</strong><span class="gg-badge" :class="`gg-${tone(s.status)}`">{{ label(s.status) }}</span></div><p>{{ s.note || '以当前来源及发布版本为准。' }}</p><a v-if="s.source_uri" :href="String(s.source_uri)" target="_blank" rel="noopener noreferrer">查看来源<Icon name="external" :size="12"/></a></article></div></section>
</template>
<template v-else-if="page==='experiments'">
 <section class="gg-card gg-research-guide"><div class="gg-card-heading"><div><h2>把研究放回保单业务</h2><p>固定责任或研究假设，冻结数据与方法，再运行和核查历史表现</p></div><span class="gg-chip">研究不自动触发交易</span></div><div class="gg-three-notes"><div><span>01</span><strong>冻结数据快照</strong><p>选择指标、样本期间及历史可用时点。</p><button v-if="canResearch" class="gg-text-btn" @click="createDataset">创建快照<Icon name="plus" :size="14"/></button></div><div><span>02</span><strong>配置因子</strong><p>从滞后、变化率、均值和波动等算子选择。</p><button v-if="canResearch" class="gg-text-btn" @click="createFactor">新建研究因子<Icon name="plus" :size="14"/></button></div><div><span>03</span><strong>运行与验证</strong><p>选择注册模型，保留基线和时间切分。</p><button v-if="canResearch" class="gg-text-btn" :disabled="!datasets.length" @click="createRun">新建研究实验<Icon name="arrow" :size="14"/></button></div></div></section>
 <div class="gg-two-columns"><section class="gg-card"><div class="gg-card-heading"><div><h2>冻结数据集<span class="gg-counter">{{ datasets.length }}</span></h2><p>后续数据修订不覆盖原样本</p></div><Icon name="file" :size="19"/></div><div v-if="!datasets.length" class="gg-empty gg-small-empty"><strong>尚未保存研究快照</strong><span>从数据浏览或创建快照开始。</span></div><div v-for="d in datasets.slice(0,4)" :key="d.id" class="gg-research-object"><span class="gg-task-icon"><Icon name="file" :size="17"/></span><div><strong>{{ d.name }}</strong><small>{{ d.row_count }} 个观测 · v{{ d.version }} · {{ d.id }}</small></div><span class="gg-badge gg-info">只读</span></div></section><section class="gg-card"><div class="gg-card-heading"><div><h2>因子版本<span class="gg-counter">{{ factors.length }}</span></h2><p>受控表达式，结果可追溯</p></div><Icon name="spark" :size="19"/></div><div v-if="!factors.length" class="gg-empty gg-small-empty"><strong>尚未配置研究因子</strong><span>使用可视化算子保存第一个因子。</span></div><div v-for="f in factors.slice(0,4)" :key="f.id" class="gg-research-object"><span class="gg-task-icon"><Icon name="spark" :size="17"/></span><div><strong>{{ f.name }}</strong><small>{{ label(f.operator) }} · 窗口 {{ f.window }} · 滞后 {{ f.lag }} · v{{ f.version }}</small></div></div></section></div>
 <RecordTable title="研究实验与历史验证" :records="runs" :columns="runCols" @select="selectedRun=$event" @export="downloadCsv('研究实验',runCols,$event)"/>
 <div v-if="selectedRun?.target_definition" class="gg-notice"><Icon name="info" :size="16"/><span>研究目标定义：{{ selectedRun.target_definition }}。此结果为研究假设，不替代保单合同采价或正式核赔。</span></div>
 <div v-for="warning in ((selectedRun?.warnings || []) as string[])" :key="warning" class="gg-notice"><Icon name="warning" :size="16"/><span>{{ warning }}</span></div>
 <section v-if="selectedRun" class="gg-card gg-run-result"><div class="gg-card-heading"><div><span class="gg-overline">{{ selectedRun.id }} · {{ label(selectedRun.target) }}</span><h2>{{ selectedRun.name }}</h2><p>{{ selectedRun.message }}</p></div><span class="gg-badge" :class="`gg-${tone(selectedRun.status)}`">{{ label(selectedRun.status) }}</span></div><div v-if="metrics?.model" class="gg-metric-comparison"><div><span>模型 MAE</span><strong>{{ fmt(metrics.model.mae) }}</strong><small>{{ selectedRun.target==='payout'?'元':'元/吨' }}</small></div><div><span>基线 MAE</span><strong>{{ fmt(metrics.baseline?.mae) }}</strong><small>{{ selectedRun.target==='payout'?'元':'元/吨' }}</small></div><div><span>模型 RMSE</span><strong>{{ fmt(metrics.model.rmse) }}</strong><small>与同口径基线比较</small></div></div><SeriesChart v-if="predictions.length" :points="predictions.map(p=>({date:String(p.date),value:p.predicted as number}))"/><div v-if="validation?.notice" class="gg-notice"><Icon name="info" :size="16"/><span>{{ validation.notice }}</span></div><div class="gg-inline-actions"><button v-if="canResearch&&selectedRun.status==='succeeded'" class="gg-btn gg-btn-primary" @click="createReport(selectedRun)">保存研究报告<Icon name="arrow" :size="16"/></button><button class="gg-btn" @click="downloadReport(selectedRun)"><Icon name="download" :size="16"/>导出实验结果</button></div><details class="gg-query-advanced"><summary>输入版本、时间切分及验证详情</summary><pre class="gg-json">{{ display({dataset_id:selectedRun.dataset_id,factor_ids:selectedRun.factor_ids,model_id:selectedRun.model_id,parameters:selectedRun.parameters,train_end:selectedRun.train_end,validation_end:selectedRun.validation_end,test_end:selectedRun.test_end,splits:selectedRun.splits,validation:selectedRun.validation}) }}</pre></details></section>
</template>
<template v-else>
 <div class="gg-context-strip"><span><Icon name="file" :size="17"/>研究依据 · 只读版本</span><p>保留研究问题、数据与方法、历史验证及业务结论</p><button class="gg-btn" @click="loadResearch"><Icon name="refresh" :size="16"/>刷新报告</button></div>
 <RecordTable title="研究报告与业务引用" :records="reports" :columns="reportCols" empty="暂无研究报告；在成功实验中保存结论后即可生成只读报告" @select="selectedReport=$event" @export="downloadCsv('研究报告目录',reportCols,$event)"/>
 <section v-if="selectedReport" class="gg-card gg-report-document"><div class="gg-card-heading"><div><span class="gg-overline">研究报告 · v{{ selectedReport.version }}</span><h2>{{ selectedReport.name }}</h2><p>{{ selectedReport.id }} · {{ date(selectedReport.created_at) }}</p></div><Icon name="file" :size="28"/></div><div class="gg-report-conclusion"><span>业务结论与使用限制</span><p>{{ selectedReport.conclusion }}</p></div><div class="gg-inline-actions"><button class="gg-btn" @click="downloadReport(selectedReport)"><Icon name="download" :size="16"/>下载报告档案</button><button v-if="canResearch" class="gg-btn gg-btn-primary" @click="emit('reference',selectedReport.id)">引用到对冲方案<Icon name="arrow" :size="15"/></button></div><details class="gg-query-advanced"><summary>查看完整只读输入与结果快照</summary><dl class="gg-facts"><div v-for="[key,value] in reportSections" :key="key"><dt>{{ key }}</dt><dd><pre v-if="typeof value==='object'" class="gg-json">{{ display(value) }}</pre><template v-else>{{ label(value) }}</template></dd></div></dl></details></section>
 <div class="gg-inline-help"><Icon name="info" :size="17"/><p>研究用于承保、赔付风险与风险转移判断。报告引用不会修改保单，也不会绕过复核下单或付款。</p></div>
</template>
<CommandDialog v-if="form" :form="form" :busy="modalBusy" :error="modalError" @close="form=null" @submit="submit"/>
<DataImport v-if="importOpen" :project-id="projectId" @close="importOpen=false" @imported="imported"/>
</template>
